'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { 
  GraduationCap, 
  Menu, 
  CloudCheck, 
  CloudUpload, 
  Sun, 
  Moon, 
  Key, 
  LogOut, 
  ShieldCheck, 
  ChevronDown,
  Edit3,
  User as UserIcon,
  Activity,
  AlertCircle,
  CheckCircle2,
  ExternalLink,
  Sparkles,
  ArrowLeft,
  Download,
  Printer
} from 'lucide-react';
import { useTheme } from './ThemeProvider';
import { logoutSession } from '@/lib/auth-client';

interface HeaderProps {
  canEdit?: boolean;
  examTitle: string;
  onUpdateTitle: (newTitle: string) => void;
  isSidebarCollapsed: boolean;
  onToggleSidebar: () => void;
  onOpenApiKeyModal: () => void;
  hasActiveKey: boolean;
  keyCount?: number;
  keyErrorCount?: number;
  quota?: {
    dailyLimit: number;
    usedToday: number;
    remaining: number;
  };
  isCloudSaving?: boolean;
  isCloudSaved?: boolean;
  currentUser?: {
    id: string;
    name: string;
    email: string;
    role: string;
  } | null;
  onToggleCopilot?: () => void;
  isCopilotOpen?: boolean;
  onExportWord?: () => void;
  onPrintPdf?: () => void;
}

export const Header: React.FC<HeaderProps> = ({
  canEdit = true,
  examTitle,
  onUpdateTitle,
  isSidebarCollapsed,
  onToggleSidebar,
  onOpenApiKeyModal,
  hasActiveKey,
  keyCount = 0,
  keyErrorCount = 0,
  quota = { dailyLimit: 100, usedToday: 0, remaining: 100 },
  isCloudSaving = false,
  isCloudSaved = true,
  currentUser = null,
  onToggleCopilot,
  isCopilotOpen = false,
  onExportWord,
  onPrintPdf,
}) => {
  const router = useRouter();
  const { theme, toggleTheme } = useTheme();
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [titleDraft, setTitleDraft] = useState({ source: examTitle, value: examTitle });
  const tempTitle = titleDraft.source === examTitle ? titleDraft.value : examTitle;
  const setTempTitle = (value: string) => setTitleDraft({ source: examTitle, value });
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const [logoutError, setLogoutError] = useState('');
  const [loggingOut, setLoggingOut] = useState(false);

  const handleTitleSubmit = () => {
    setIsEditingTitle(false);
    if (tempTitle.trim() && tempTitle.trim() !== examTitle) {
      onUpdateTitle(tempTitle.trim());
    } else {
      setTempTitle(examTitle);
    }
  };

  const handleLogout = async () => {
    if (loggingOut) return;
    setLoggingOut(true); setLogoutError('');
    try {
      await logoutSession(currentUser?.id);
      router.push('/login'); router.refresh();
    } catch (error) { setLogoutError(error instanceof Error ? error.message : 'Chưa đăng xuất được. Vui lòng thử lại.'); }
    finally { setLoggingOut(false); }
  };

  const usagePercent = quota.dailyLimit > 0 
    ? Math.min(100, Math.round((quota.usedToday / quota.dailyLimit) * 100))
    : 0;

  return (
    <header className="no-print h-14 bg-white dark:bg-[#181818] border-b border-[#dadce0] dark:border-[#3c4043] shrink-0 z-30 px-3 sm:px-5 flex items-center justify-between gap-3 shadow-xs transition-colors duration-200">
      {/* KHU VỰC TRÁI: Toggle menu, Logo ExamCraft, Tiêu đề đề thi & Trạng thái lưu Google Docs style */}
      <div className="flex items-center gap-3 sm:gap-4 flex-1 min-w-0">
        {/* Nút toggle Sidebar */}
        <button
          onClick={onToggleSidebar}
          title={isSidebarCollapsed ? 'Mở rộng bảng công cụ' : 'Thu gọn bảng công cụ'}
          className="p-2 rounded-full text-[#5f6368] hover:text-[#202124] dark:text-[#9aa0a6] dark:hover:text-[#e3e3e3] hover:bg-[#f1f3f4] dark:hover:bg-[#282828] transition-colors cursor-pointer"
        >
          <Menu className="w-5 h-5" />
        </button>

        {/* Logo ExamCraft Google Style */}
        <Link href="/" className="flex items-center gap-2.5 shrink-0 group">
          <div className="w-8 h-8 rounded-full bg-[#202124] dark:bg-[#282828] text-white dark:text-[#8ab4f8] border border-transparent dark:border-[#3c4043] flex items-center justify-center shadow-xs group-hover:scale-105 transition-transform">
            <GraduationCap className="w-4 h-4" />
          </div>
          <span className="font-bold text-[#202124] dark:text-[#e3e3e3] text-base sm:text-lg tracking-tight hidden sm:inline">
            ExamCraft
          </span>
        </Link>

        {/* Nút Quay lại Kho đề của tôi */}
        <Link
          href="/"
          title="Quay về Kho đề của tôi (Lưu tự động)"
          className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold text-[#5f6368] hover:text-[#1a73e8] hover:bg-[#f1f3f4] dark:hover:bg-[#282828] border border-[#dadce0] dark:border-[#3c4043] transition-colors cursor-pointer shrink-0"
        >
          <ArrowLeft className="w-3.5 h-3.5" />
          <span className="hidden sm:inline">Kho đề</span>
        </Link>

        {/* Ngăn cách thanh mảnh */}
        <div className="h-5 w-[1px] bg-[#dadce0] dark:bg-[#3c4043] hidden sm:block shrink-0" />

        {/* Tên đề thi (Sửa trực tiếp phong cách Google Docs) */}
        <div className="flex items-center gap-2 min-w-0 flex-1 max-w-xl">
          {isEditingTitle ? (
            <input
              type="text"
              autoFocus
              value={tempTitle}
              onChange={(e) => setTempTitle(e.target.value)}
              onBlur={handleTitleSubmit}
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleTitleSubmit();
                if (e.key === 'Escape') {
                  setTempTitle(examTitle);
                  setIsEditingTitle(false);
                }
              }}
              className="text-sm font-semibold text-[#202124] dark:text-[#e3e3e3] bg-white dark:bg-[#282828] border border-[#1a73e8] dark:border-[#8ab4f8] rounded-md px-2 py-0.5 outline-hidden w-full shadow-xs"
            />
          ) : (
            <button
              disabled={!canEdit}
              onClick={() => {
                setTempTitle(examTitle);
                setIsEditingTitle(true);
              }}
              title="Nhấn để đổi tên đề thi (như Google Docs)"
              className="group flex items-center gap-1.5 text-sm font-semibold text-[#202124] dark:text-[#e3e3e3] hover:bg-[#f1f3f4] dark:hover:bg-[#282828] px-2 py-1 rounded-md transition-colors truncate text-left cursor-pointer"
            >
              <span className="truncate">{examTitle || 'Đề kiểm tra không tên'}</span>
              <Edit3 className="w-3.5 h-3.5 text-[#5f6368] opacity-0 group-hover:opacity-100 transition-opacity shrink-0" />
            </button>
          )}

          {/* Trạng thái Auto-save giống Google Docs ("Đã lưu vào Drive") */}
          <div className="hidden md:flex items-center gap-1 text-[11px] text-[#5f6368] dark:text-[#9aa0a6] shrink-0">
            {isCloudSaving ? (
              <span className="flex items-center gap-1 text-[#1a73e8] dark:text-[#8ab4f8]">
                <CloudUpload className="w-3.5 h-3.5 animate-bounce" />
                <span>Đang lưu...</span>
              </span>
            ) : isCloudSaved ? (
              <span className="flex items-center gap-1 text-[#5f6368] dark:text-[#9aa0a6]">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
                <span>Đã lưu trên máy chủ</span>
              </span>
            ) : (
              <span className="flex items-center gap-1 text-amber-500">
                <span className="w-1.5 h-1.5 rounded-full bg-amber-500" />
                <span>Chưa lưu</span>
              </span>
            )}
          </div>
        </div>
      </div>

      {/* KHU VỰC PHẢI: Dark Mode, Nút Khóa AI, Gemini Toggle, Avatar User & Menu Giám sát */}
      <div className="flex items-center gap-2 sm:gap-2.5 shrink-0">
        {/* Nút xuất bản nhanh lên Header */}
        <div className="hidden sm:flex items-center gap-2 pr-2 border-r border-[#dadce0] dark:border-[#3c4043]">
          {onExportWord && (
            <button
              onClick={onExportWord}
              title="Tải file Word (.docx) chuẩn công thức OMML"
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold bg-[#1a73e8] hover:bg-[#1557b0] text-white shadow-2xs transition-colors cursor-pointer"
            >
              <Download className="w-3.5 h-3.5" />
              <span className="hidden md:inline">Tải Word (.docx)</span>
            </button>
          )}
          {onPrintPdf && (
            <button
              onClick={onPrintPdf}
              title="In đề thi hoặc xuất ra PDF"
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold bg-white dark:bg-[#282828] border border-[#dadce0] dark:border-[#3c4043] text-[#3c4043] dark:text-[#e3e3e3] hover:bg-[#f8f9fa] shadow-2xs transition-colors cursor-pointer"
            >
              <Printer className="w-3.5 h-3.5" />
              <span className="hidden md:inline">In / PDF</span>
            </button>
          )}
        </div>

        {/* Nút bật/tắt Bảng Trợ lý AI Gemini (Right Companion Rail) */}
        {onToggleCopilot && (
          <button
            onClick={onToggleCopilot}
            title={isCopilotOpen ? "Đóng thanh trợ lý AI Gemini (Cột phải)" : "Mở thanh trợ lý AI Gemini (Cột phải)"}
            className={`p-2 rounded-full transition-colors cursor-pointer flex items-center gap-1.5 text-xs font-medium ${
              isCopilotOpen
                ? 'bg-[#e8f0fe] dark:bg-[#1e2a38] text-[#1a73e8] dark:text-[#8ab4f8] border border-blue-200 dark:border-[#3c4043]'
                : 'text-[#5f6368] hover:text-[#202124] dark:text-[#9aa0a6] dark:hover:text-[#e3e3e3] hover:bg-[#f1f3f4] dark:hover:bg-[#282828]'
            }`}
          >
            <Sparkles className="w-4 h-4 text-amber-500 shrink-0" />
            <span className="hidden md:inline">Gemini AI</span>
          </button>
        )}

        {/* Nút bật/tắt Dark Mode */}
        <button
          onClick={toggleTheme}
          title={theme === 'dark' ? 'Chuyển sang chế độ Sáng (Màu trắng Google)' : 'Chuyển sang chế độ Tối (Dark Mode)'}
          className="p-2 rounded-full text-[#5f6368] hover:text-[#202124] dark:text-[#9aa0a6] dark:hover:text-[#e3e3e3] hover:bg-[#f1f3f4] dark:hover:bg-[#282828] transition-colors cursor-pointer"
        >
          {theme === 'dark' ? <Sun className="w-4 h-4 text-amber-400" /> : <Moon className="w-4 h-4 text-[#5f6368]" />}
        </button>

        {/* Nút Trạng thái Khóa AI cá nhân (Badge Google Minimalist) */}
        <button
          onClick={onOpenApiKeyModal}
          title={
            !hasActiveKey
              ? 'Tài khoản chưa có API Key: Nhấn để thêm khóa cá nhân'
              : keyErrorCount > 0
              ? `Có ${keyErrorCount} khóa bị lỗi hoặc hết lượt (429)!`
              : `Khóa AI Google Gemini: ${keyCount} khóa đang hoạt động tốt`
          }
          className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium transition-all border cursor-pointer shadow-2xs ${
            !hasActiveKey
              ? 'bg-amber-50 dark:bg-amber-950/40 text-amber-800 dark:text-amber-300 border-amber-200 dark:border-amber-800 hover:bg-amber-100'
              : keyErrorCount > 0
              ? 'bg-rose-50 dark:bg-rose-950/40 text-rose-800 dark:text-rose-300 border-rose-200 dark:border-rose-800 hover:bg-rose-100'
              : 'bg-white dark:bg-[#282828] text-[#3c4043] dark:text-[#e3e3e3] border-[#dadce0] dark:border-[#3c4043] hover:bg-[#f8f9fa] dark:hover:bg-[#303134]'
          }`}
        >
          <Key className="w-3.5 h-3.5 text-[#5f6368] dark:text-[#9aa0a6]" />
          <span className="hidden sm:inline">Khóa AI</span>
          {keyCount > 0 && <span className="font-mono text-[11px] font-semibold">({keyCount})</span>}
          <span
            className={`w-2 h-2 rounded-full ${
              !hasActiveKey
                ? 'bg-amber-500 animate-pulse'
                : keyErrorCount > 0
                ? 'bg-rose-500 animate-pulse'
                : 'bg-emerald-500'
            }`}
          />
        </button>

        {/* Avatar & Dropdown Menu với Bảng Theo Dõi Khóa AI Trực Quan */}
        {currentUser ? (
          <div className="relative">
            <button
              onClick={() => setIsUserMenuOpen(!isUserMenuOpen)}
              className="flex items-center gap-2 py-1 px-1.5 sm:px-2 rounded-full hover:bg-[#f1f3f4] dark:hover:bg-[#282828] transition-colors cursor-pointer"
            >
              <div className="w-7 h-7 rounded-full bg-[#202124] dark:bg-[#282828] text-white dark:text-[#8ab4f8] border border-transparent dark:border-[#3c4043] flex items-center justify-center text-xs font-bold shadow-xs">
                {currentUser.name ? currentUser.name.charAt(0).toUpperCase() : 'U'}
              </div>
              <ChevronDown className="w-3.5 h-3.5 text-[#5f6368] dark:text-[#9aa0a6] hidden sm:block" />
            </button>

            {isUserMenuOpen && (
              <>
                <div 
                  className="fixed inset-0 z-40" 
                  onClick={() => setIsUserMenuOpen(false)} 
                />
                <div className="absolute right-0 mt-2 w-72 bg-white dark:bg-[#1e1e1e] border border-[#dadce0] dark:border-[#3c4043] rounded-3xl shadow-2xl z-50 p-2.5 text-xs divide-y divide-[#f1f3f4] dark:divide-[#3c4043] animate-in fade-in zoom-in-95 duration-100">
                  {/* THÔNG TIN NGƯỜI DÙNG */}
                  <div className="p-2">
                    <p className="font-bold text-[#202124] dark:text-[#e3e3e3] text-sm truncate">{currentUser.name}</p>
                    <p className="text-[11px] text-[#5f6368] dark:text-[#9aa0a6] truncate">{currentUser.email}</p>
                    <span className="inline-block mt-1 px-2 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider bg-[#e8f0fe] dark:bg-[#1e2a38] text-[#1a73e8] dark:text-[#8ab4f8]">
                      {currentUser.role === 'SUPER_ADMIN' ? 'Quản trị viên' : 'Giáo viên'}
                    </span>
                  </div>

                  {/* KHỐI THEO DÕI TRẠNG THÁI KHÓA AI & HẠN MỨC */}
                  <div className="py-2.5">
                    <div className="p-3 bg-[#f8f9fa] dark:bg-[#282828]/60 rounded-2xl border border-[#dadce0] dark:border-[#3c4043] space-y-2">
                      <div className="flex items-center justify-between">
                        <span className="text-[11px] font-bold text-[#3c4043] dark:text-[#e3e3e3] flex items-center gap-1.5">
                          <Activity className="w-3.5 h-3.5 text-[#1a73e8] dark:text-[#8ab4f8]" />
                          <span>Kho Khóa AI Của Bạn</span>
                        </span>
                        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${
                          !hasActiveKey
                            ? 'bg-amber-100 text-amber-800 dark:bg-amber-950/60 dark:text-amber-300'
                            : keyErrorCount > 0
                            ? 'bg-rose-100 text-rose-800 dark:bg-rose-950/60 dark:text-rose-300'
                            : 'bg-emerald-100 text-emerald-800 dark:bg-emerald-950/60 dark:text-emerald-300'
                        }`}>
                          {!hasActiveKey 
                            ? 'Chưa có key' 
                            : keyErrorCount > 0 
                            ? `${keyErrorCount} key lỗi/429` 
                            : `${keyCount} key sẵn sàng`}
                        </span>
                      </div>

                      {/* Thanh tiến trình hạn mức hôm nay */}
                      <div className="space-y-1">
                        <div className="flex items-center justify-between text-[11px] text-[#5f6368] dark:text-[#9aa0a6]">
                          <span>Đã dùng hôm nay:</span>
                          <span className="font-bold text-[#202124] dark:text-[#e3e3e3]">{quota.usedToday} / {quota.dailyLimit} lượt</span>
                        </div>
                        <div className="w-full bg-[#dadce0] dark:bg-[#3c4043] h-1.5 rounded-full overflow-hidden">
                          <div 
                            className={`h-full rounded-full transition-all duration-300 ${
                              usagePercent > 80 ? 'bg-rose-500' : 'bg-[#1a73e8] dark:bg-[#8ab4f8]'
                            }`}
                            style={{ width: `${usagePercent}%` }}
                          />
                        </div>
                        <div className="text-[10px] text-emerald-600 dark:text-emerald-400 flex items-center justify-between">
                          <span>Còn lại: {quota.remaining} lượt</span>
                          <span className="text-[#5f6368] dark:text-[#9aa0a6] font-sans">({usagePercent}%)</span>
                        </div>
                      </div>

                      {/* Cảnh báo trạng thái */}
                      {!hasActiveKey ? (
                        <p className="text-[11px] text-amber-700 dark:text-amber-300 flex items-center gap-1.5 pt-0.5">
                          <AlertCircle className="w-3.5 h-3.5 shrink-0 text-amber-600" />
                          <span>Chưa thêm khóa AI cá nhân!</span>
                        </p>
                      ) : keyErrorCount > 0 ? (
                        <p className="text-[11px] text-rose-600 dark:text-rose-400 flex items-center gap-1.5 pt-0.5">
                          <AlertCircle className="w-3.5 h-3.5 shrink-0 text-rose-600" />
                          <span>Có khóa đang chạm hạn mức 429!</span>
                        </p>
                      ) : (
                        <p className="text-[11px] text-emerald-700 dark:text-emerald-300 flex items-center gap-1.5 pt-0.5">
                          <CheckCircle2 className="w-3.5 h-3.5 shrink-0 text-emerald-600" />
                          <span>Tự động xoay tua đa khóa sẵn sàng</span>
                        </p>
                      )}

                      {/* Nút bấm mở nhanh Modal Quản lý API Key */}
                      <button
                        onClick={() => {
                          setIsUserMenuOpen(false);
                          onOpenApiKeyModal();
                        }}
                        className="w-full mt-1 py-2 px-3 bg-[#202124] hover:bg-[#303134] text-white dark:bg-[#282828] dark:text-[#e3e3e3] dark:hover:bg-[#303134] dark:border dark:border-[#3c4043] rounded-full font-medium text-xs flex items-center justify-center gap-1.5 shadow-2xs transition-colors cursor-pointer"
                      >
                        <Key className="w-3.5 h-3.5" />
                        <span>Quản lý & Kiểm tra Khóa AI</span>
                      </button>
                    </div>
                  </div>

                  {currentUser.role === 'SUPER_ADMIN' && (
                    <div className="py-1">
                      <Link
                        href="/admin/users"
                        onClick={() => setIsUserMenuOpen(false)}
                        className="flex items-center gap-2 px-2.5 py-1.5 rounded-full text-[#3c4043] dark:text-[#e3e3e3] hover:bg-[#f1f3f4] dark:hover:bg-[#282828] transition-colors"
                      >
                        <ShieldCheck className="w-4 h-4 text-[#1a73e8] dark:text-[#8ab4f8]" />
                        <span>Quản trị người dùng</span>
                      </Link>
                    </div>
                  )}

                  <div className="pt-1">
                    <button
                      onClick={handleLogout}
                        disabled={loggingOut}
                      className="w-full flex items-center gap-2 px-2.5 py-1.5 rounded-full text-rose-600 dark:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-950/40 transition-colors cursor-pointer"
                    >
                      <LogOut className="w-4 h-4" />
                      <span>Đăng xuất tài khoản</span>
                    </button>
                      {logoutError && <p role="alert" className="mt-2 text-xs text-red-600 dark:text-red-300">{logoutError}</p>}
                  </div>
                </div>
              </>
            )}
          </div>
        ) : (
          <Link
            href="/login"
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold text-white bg-blue-600 hover:bg-blue-700 shadow-xs transition-colors"
          >
            <UserIcon className="w-3.5 h-3.5" />
            <span>Đăng nhập</span>
          </Link>
        )}
      </div>
    </header>
  );
};

'use client';

import React, { useState, useEffect, useRef, useSyncExternalStore } from 'react';
import { accountFetch } from '@/lib/account-fetch';
import { Exam } from '@/types/exam';
import { persistExam } from '@/lib/exam-client';
import { buildAssignmentOptions } from '@/lib/assignment-options';
import { ExamReviewPanel } from '@/components/ExamReviewPanel';
import Link from 'next/link';
import {
  Share2,
  Copy,
  CheckCircle2,
  ExternalLink,
  Users,
  FileDown,
  X,
  PlayCircle,
  Clock,
  Settings,
  Sparkles,
  Trophy,
  Shield,
  HelpCircle,
} from 'lucide-react';

/** Share links end in `.v<version>` (see src/lib/share-version.ts, which is server-only). */
const pinnedVersionOf = (path: string) => /\.v(\d{1,9})$/.exec(path)?.[1] ?? '';

const subscribeOrigin = () => () => {};
const browserOrigin = () => window.location.origin;
const serverOrigin = () => '';

interface GroupItem {
  id: string;
  name: string;
  publicCode: string;
  _count: { students: number };
}

interface ShareModalProps {
  ownerId: string;
  isOpen: boolean;
  onClose: () => void;
  exam: Exam;
  onEnsureSaved?: () => Promise<Exam | null>;
  onCloudSyncSuccess?: () => void;
}

export const ShareModal: React.FC<ShareModalProps> = ({
  ownerId,
  isOpen,
  onClose,
  exam,
  onEnsureSaved,
  onCloudSyncSuccess,
}) => {
  const active = useRef(isOpen);
  useEffect(() => { active.current = isOpen; return () => { active.current = false; }; }, [isOpen]);
  const [activeTab, setActiveTab] = useState<'assign' | 'share'>('assign');
  const origin = useSyncExternalStore(subscribeOrigin, browserOrigin, serverOrigin);

  // Trạng thái Lớp học
  const [groups, setGroups] = useState<GroupItem[]>([]);
  const [selectedGroupId, setSelectedGroupId] = useState<string>('');
  const [loadingGroups, setLoadingGroups] = useState(false);

  // Cấu hình giao bài
  const [titleDraft, setTitleDraft] = useState({ source: exam.metadata.title, value: exam.metadata.title || 'Bài kiểm tra trực tuyến' });
  const assignmentTitle = exam.metadata.title && titleDraft.source !== exam.metadata.title ? exam.metadata.title : titleDraft.value;
  const setAssignmentTitle = (value: string) => setTitleDraft({ source: exam.metadata.title, value });
  const [mode, setMode] = useState<'HOMEWORK' | 'CLASSWORK' | 'EXAM'>('CLASSWORK');
  const [identityMode, setIdentityMode] = useState<'PICK_FROM_LIST' | 'FREE_NAME'>('PICK_FROM_LIST');
  const [durationMinutes, setDurationMinutes] = useState<number>(
    exam?.metadata?.durationMinutes || 45
  );
  const [showResult, setShowResult] = useState<'IMMEDIATE' | 'AFTER_CLOSE' | 'NEVER'>('IMMEDIATE');
  const [showSolution, setShowSolution] = useState<'IMMEDIATE' | 'AFTER_CLOSE' | 'NEVER'>('AFTER_CLOSE');
  const [enableLeaderboard, setEnableLeaderboard] = useState<boolean>(false);
  // Tùy chọn nâng cao: để trống = giữ hành vi cũ (mở ngay, không hạn đóng, 1 lượt cho phòng thi, 3 lượt cho loại khác)
  const [opensAtLocal, setOpensAtLocal] = useState('');
  const [closesAtLocal, setClosesAtLocal] = useState('');
  const [maxAttemptsText, setMaxAttemptsText] = useState('');
  const [joinCodeText, setJoinCodeText] = useState('');
  const [requirePin, setRequirePin] = useState(false);
  const [shuffleQuestions, setShuffleQuestions] = useState(false);
  const [shuffleChoices, setShuffleChoices] = useState(false);
  const [optionsError, setOptionsError] = useState('');

  // Trạng thái giao bài
  const [assigning, setAssigning] = useState(false);
  const [createdPublicLink, setCreatedPublicLink] = useState<string | null>(null);
  const [copiedLink, setCopiedLink] = useState(false);
  const [copiedShareLink, setCopiedShareLink] = useState(false);
  const [sharePath, setSharePath] = useState('');
  const [shareLinkId, setShareLinkId] = useState('');
  const [shareExamId, setShareExamId] = useState('');
  const [sharing, setSharing] = useState(false);
  const [shareAnswers, setShareAnswers] = useState(false);
  const [shareCopy, setShareCopy] = useState(false);

  // Tải danh sách lớp của giáo viên
  useEffect(() => {
    const controller = new AbortController();
    if (isOpen) {
      async function loadGroups() {
        try {
          setLoadingGroups(true);
          const res = await accountFetch(ownerId, '/api/groups', { signal: controller.signal, cache: 'no-store' });
          const data = await res.json();
          if (controller.signal.aborted) return;
          if (res.ok && data.groups) {
            setGroups(data.groups);
            if (data.groups.length > 0) {
              setSelectedGroupId(data.groups[0].id);
            }
          }
        } catch (err) {
          console.error(err);
        } finally {
          if (!controller.signal.aborted) setLoadingGroups(false);
        }
      }
      loadGroups();
    }
    return () => controller.abort();
  }, [isOpen, ownerId]);

  if (!isOpen) return null;

  // Xử lý Giao bài lên Server DB (Tạo bản chụp Snapshot bất biến)
  const handleAssignExam = async (e: React.FormEvent) => {
    e.preventDefault();
    const options = buildAssignmentOptions({
      opensAtLocal, closesAtLocal, maxAttempts: maxAttemptsText, defaultMaxAttempts: mode === 'EXAM' ? 1 : 3,
      joinCode: joinCodeText, requirePin, shuffleQuestions, shuffleChoices,
      hasGroup: Boolean(selectedGroupId), identityMode: selectedGroupId ? identityMode : 'FREE_NAME',
    });
    if (!options.ok) { setOptionsError(options.error); return; }
    setOptionsError('');
    try {
      setAssigning(true);

      const savedExam = onEnsureSaved ? await onEnsureSaved() : await persistExam(exam, ownerId);
      if (!active.current) return;
      if (!savedExam) throw new Error('Đề chưa được lưu. Hãy xử lý trạng thái lưu trước khi giao bài.');
      const serverExamId = savedExam.id;

      // 2. Tạo Assignment với snapshot bất biến
      const assignRes = await accountFetch(ownerId, '/api/assignments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          examId: serverExamId,
          groupId: selectedGroupId || undefined,
          title: assignmentTitle.trim(),
          mode,
          identityMode: selectedGroupId ? identityMode : 'FREE_NAME',
          durationMinutes: Number(durationMinutes) || undefined,
          ...options.payload,
          showResult,
          showSolution,
          leaderboard: enableLeaderboard ? 'TOP_AND_ME' : 'OFF',
          leaderboardTopN: 3,
        }),
      });

      const assignData = await assignRes.json();
      if (!assignRes.ok) {
        alert(assignData.error || 'Lỗi khi giao bài');
        return;
      }

      setCreatedPublicLink(assignData.publicLink);
      if (onCloudSyncSuccess) onCloudSyncSuccess();
    } catch (err) {
      console.error('Lỗi khi giao bài:', err);
      alert(err instanceof Error ? err.message : 'Không thể kết nối đến máy chủ.');
    } finally {
      setAssigning(false);
    }
  };

  const copyToClipboard = (text: string, type: 'assign' | 'share') => {
    navigator.clipboard.writeText(text);
    if (type === 'assign') {
      setCopiedLink(true);
      setTimeout(() => setCopiedLink(false), 2000);
    } else {
      setCopiedShareLink(true);
      setTimeout(() => setCopiedShareLink(false), 2000);
    }
  };

  const fullAssignUrl = createdPublicLink ? `${origin}${createdPublicLink}` : '';
  const shareWordUrl = sharePath ? origin + sharePath : '';
  const createShareLink = async () => {
    setSharing(true);
    try {
      const saved = onEnsureSaved ? await onEnsureSaved() : await persistExam(exam, ownerId);
      if (!active.current) return;
      if (!saved) throw new Error('Đề chưa được lưu. Hãy xử lý trạng thái lưu trước khi chia sẻ.');
      const id = saved.id;
      const response = await accountFetch(ownerId, '/api/exams/' + id + '/share', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ showAnswers: shareAnswers, allowCopy: shareCopy, expiresAt: new Date(Date.now() + 7 * 86400000).toISOString() }) });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Chưa tạo được link');
      setSharePath(data.publicLink); setShareLinkId(data.link.id); setShareExamId(id); onCloudSyncSuccess?.();
    } catch (error) { alert(error instanceof Error ? error.message : 'Chưa tạo được link'); }
    finally { setSharing(false); }
  };
  const revokeShareLink = async () => {
    const response = await accountFetch(ownerId, '/api/exams/' + shareExamId + '/share', { method: 'DELETE', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ linkId: shareLinkId }) });
    if (response.ok) { setSharePath(''); setShareLinkId(''); } else alert('Chưa thu hồi được link, hãy thử lại');
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-xs flex items-center justify-center p-4">
      <div className="bg-white dark:bg-[#1e1e1e] border border-[#dadce0] dark:border-[#3c4043] rounded-3xl max-w-xl w-full p-6 shadow-2xl text-[#202124] dark:text-[#e3e3e3] max-h-[92vh] overflow-y-auto animate-in fade-in zoom-in-95 duration-150">
        <ExamReviewPanel exam={exam} />
        {/* Header Modal */}
        <div className="flex items-center justify-between pb-4 border-b border-[#dadce0] dark:border-[#3c4043]">
          <div className="flex items-center gap-2.5">
            <div className="w-10 h-10 rounded-2xl bg-[#e8f0fe] dark:bg-[#1e2a38] text-[#1a73e8] dark:text-[#8ab4f8] flex items-center justify-center border border-[#d2e3fc] dark:border-[#29425e] shadow-xs">
              <Share2 className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-base font-bold text-[#202124] dark:text-[#e3e3e3]">Chia Sẻ & Giao Bài Thi Trực Tuyến</h3>
              <p className="text-xs text-[#5f6368] dark:text-[#9aa0a6]">Tạo phòng thi có chấm điểm tự động hoặc link tải Word</p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-full text-[#5f6368] dark:text-[#9aa0a6] hover:text-[#202124] dark:hover:text-[#e3e3e3] hover:bg-[#f1f3f4] dark:hover:bg-[#282828] transition-colors cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Tab Switcher */}
        <div className="flex p-1 bg-[#f1f3f4] dark:bg-[#282828] rounded-full my-4 border border-[#dadce0] dark:border-[#3c4043]">
          <button
            onClick={() => setActiveTab('assign')}
            className={`flex-1 py-2 rounded-full text-xs font-medium transition-all flex items-center justify-center gap-1.5 cursor-pointer ${
              activeTab === 'assign'
                ? 'bg-[#1a73e8] text-white dark:bg-[#8ab4f8] dark:text-[#202124] shadow-xs'
                : 'text-[#5f6368] dark:text-[#9aa0a6] hover:text-[#202124] dark:hover:text-[#e3e3e3]'
            }`}
          >
            <PlayCircle className="w-4 h-4" /> Giao Bài Thi Online (Chấm Tự Động)
          </button>
          <button
            onClick={() => setActiveTab('share')}
            className={`flex-1 py-2 rounded-full text-xs font-medium transition-all flex items-center justify-center gap-1.5 cursor-pointer ${
              activeTab === 'share'
                ? 'bg-[#1a73e8] text-white dark:bg-[#8ab4f8] dark:text-[#202124] shadow-xs'
                : 'text-[#5f6368] dark:text-[#9aa0a6] hover:text-[#202124] dark:hover:text-[#e3e3e3]'
            }`}
          >
            <FileDown className="w-4 h-4" /> Link Xem / Tải Word (.docx)
          </button>
        </div>

        {/* TAB 1: GIAO BÀI THI TRỰC TUYẾN */}
        {activeTab === 'assign' && (
          <div className="space-y-4">
            {createdPublicLink ? (
              /* MÀN HÌNH SAU KHI GIAO BÀI THÀNH CÔNG */
              <div className="p-5 rounded-2xl bg-[#e8f0fe]/50 dark:bg-[#1e2a38]/60 border border-[#d2e3fc] dark:border-[#29425e] space-y-4 text-center">
                <div className="w-12 h-12 bg-[#e6f4ea] dark:bg-[#0f291e] text-[#137333] dark:text-[#5bb98c] rounded-full flex items-center justify-center mx-auto border border-[#ceead6] dark:border-[#1d4834]">
                  <CheckCircle2 className="w-6 h-6" />
                </div>
                <div>
                  <h4 className="text-base font-bold text-[#202124] dark:text-[#e3e3e3]">Phòng Thi Trực Tuyến Đã Sẵn Sàng!</h4>
                  <p className="text-xs text-[#5f6368] dark:text-[#9aa0a6] mt-1">
                    Bản chụp đề thi bất biến đã được tạo. Học sinh không cần tài khoản, chỉ cần bấm link để làm bài.
                  </p>
                </div>

                <div className="flex items-center gap-2 bg-white dark:bg-[#1e1e1e] rounded-2xl p-2 border border-[#dadce0] dark:border-[#3c4043] text-left">
                  <input
                    type="text"
                    readOnly
                    value={fullAssignUrl}
                    className="grow bg-transparent text-xs text-[#1a73e8] dark:text-[#8ab4f8] font-mono px-2 outline-none select-all truncate"
                  />
                  <button
                    onClick={() => copyToClipboard(fullAssignUrl, 'assign')}
                    className="px-3.5 py-1.5 bg-[#1a73e8] hover:bg-[#1557b0] dark:bg-[#8ab4f8] dark:hover:bg-[#a8c7fa] text-white dark:text-[#202124] rounded-full text-xs font-medium flex items-center gap-1 shrink-0 transition-all cursor-pointer shadow-xs"
                  >
                    {copiedLink ? (
                      <>
                        <CheckCircle2 className="w-3.5 h-3.5" /> Đã chép
                      </>
                    ) : (
                      <>
                        <Copy className="w-3.5 h-3.5" /> Sao chép
                      </>
                    )}
                  </button>
                </div>

                <div className="flex gap-2 justify-center pt-2">
                  <a
                    href={createdPublicLink}
                    target="_blank"
                    rel="noreferrer"
                    className="inline-flex items-center gap-1.5 px-4 py-2 bg-white dark:bg-[#282828] hover:bg-[#f8f9fa] dark:hover:bg-[#303134] text-[#3c4043] dark:text-[#e3e3e3] border border-[#dadce0] dark:border-[#3c4043] text-xs font-medium rounded-full transition-all"
                  >
                    Vào phòng thi thử <ExternalLink className="w-3.5 h-3.5" />
                  </a>
                  <button
                    onClick={() => setCreatedPublicLink(null)}
                    className="px-4 py-2 bg-white dark:bg-[#282828] hover:bg-[#f8f9fa] dark:hover:bg-[#303134] text-[#5f6368] dark:text-[#9aa0a6] hover:text-[#202124] dark:hover:text-[#e3e3e3] border border-[#dadce0] dark:border-[#3c4043] text-xs font-medium rounded-full transition-all cursor-pointer"
                  >
                    Tạo đợt thi khác
                  </button>
                </div>
              </div>
            ) : (
              /* FORM CẤU HÌNH GIAO BÀI */
              <form onSubmit={handleAssignExam} className="space-y-4">
                <div>
                  <label className="block text-xs font-semibold text-[#5f6368] dark:text-[#9aa0a6] uppercase tracking-wider mb-1.5">
                    Tiêu đề bài giao
                  </label>
                  <input
                    type="text"
                    value={assignmentTitle}
                    onChange={(e) => setAssignmentTitle(e.target.value)}
                    className="w-full bg-white dark:bg-[#282828] border border-[#dadce0] dark:border-[#3c4043] rounded-xl px-3.5 py-2.5 text-xs sm:text-sm text-[#202124] dark:text-[#e3e3e3] focus:outline-hidden focus:border-[#1a73e8] dark:focus:border-[#8ab4f8] focus:ring-1 focus:ring-[#1a73e8] dark:focus:ring-[#8ab4f8]"
                    required
                  />
                </div>

                {/* Chọn Lớp Học */}
                <div>
                  <div className="flex items-center justify-between mb-1.5">
                    <label className="block text-xs font-semibold text-[#5f6368] dark:text-[#9aa0a6] uppercase tracking-wider">
                      Giao cho lớp học
                    </label>
                    <Link
                      href="/teacher/groups"
                      target="_blank"
                      className="text-[11px] text-[#1a73e8] dark:text-[#8ab4f8] hover:underline flex items-center gap-1"
                    >
                      <Users className="w-3 h-3" /> Quản lý danh sách lớp
                    </Link>
                  </div>
                  <select
                    aria-label="Giao cho lớp học"
                    value={selectedGroupId}
                    onChange={(e) => setSelectedGroupId(e.target.value)}
                    className="w-full bg-white dark:bg-[#282828] border border-[#dadce0] dark:border-[#3c4043] rounded-xl px-3.5 py-2.5 text-xs sm:text-sm text-[#202124] dark:text-[#e3e3e3] focus:outline-hidden focus:border-[#1a73e8] dark:focus:border-[#8ab4f8] focus:ring-1 focus:ring-[#1a73e8] dark:focus:ring-[#8ab4f8] cursor-pointer"
                  >
                    <option value="">-- Làm tự do (Học sinh tự gõ tên) --</option>
                    {groups.map((g) => (
                      <option key={g.id} value={g.id}>
                        {g.name} ({g._count.students} học sinh)
                      </option>
                    ))}
                  </select>
                </div>

                {/* Chế độ nhận diện học sinh */}
                {selectedGroupId && (
                  <div className="flex gap-4 text-xs">
                    <label className="flex items-center gap-2 cursor-pointer text-[#3c4043] dark:text-[#e3e3e3]">
                      <input
                        type="radio"
                        checked={identityMode === 'PICK_FROM_LIST'}
                        onChange={() => setIdentityMode('PICK_FROM_LIST')}
                        className="text-[#1a73e8] focus:ring-0"
                      />
                      Chọn tên từ danh sách lớp
                    </label>
                    <label className="flex items-center gap-2 cursor-pointer text-[#3c4043] dark:text-[#e3e3e3]">
                      <input
                        type="radio"
                        checked={identityMode === 'FREE_NAME'}
                        onChange={() => setIdentityMode('FREE_NAME')}
                        className="text-[#1a73e8] focus:ring-0"
                      />
                      Tự gõ tên
                    </label>
                  </div>
                )}

                {/* Bộ cấu hình nhanh (Presets) */}
                <div className="grid grid-cols-3 gap-2">
                  <button
                    type="button"
                    onClick={() => {
                      setMode('CLASSWORK');
                      setDurationMinutes(45);
                      setShowResult('IMMEDIATE');
                      setShowSolution('AFTER_CLOSE');
                    }}
                    className={`p-3 rounded-2xl border text-left transition-all cursor-pointer ${
                      mode === 'CLASSWORK'
                        ? 'bg-[#e8f0fe] dark:bg-[#1e2a38] border-[#1a73e8] dark:border-[#8ab4f8] text-[#1a73e8] dark:text-[#8ab4f8] shadow-xs'
                        : 'bg-[#f8f9fa] dark:bg-[#282828] border-[#dadce0] dark:border-[#3c4043] text-[#5f6368] dark:text-[#9aa0a6] hover:bg-[#e8eaed] dark:hover:bg-[#303134]'
                    }`}
                  >
                    <span className="text-xs font-bold block">Bài Trên Lớp</span>
                    <span className="text-[10px] opacity-80">45p, hiện điểm</span>
                  </button>

                  <button
                    type="button"
                    onClick={() => {
                      setMode('HOMEWORK');
                      setDurationMinutes(60);
                      setShowResult('IMMEDIATE');
                      setShowSolution('IMMEDIATE');
                    }}
                    className={`p-3 rounded-2xl border text-left transition-all cursor-pointer ${
                      mode === 'HOMEWORK'
                        ? 'bg-[#e8f0fe] dark:bg-[#1e2a38] border-[#1a73e8] dark:border-[#8ab4f8] text-[#1a73e8] dark:text-[#8ab4f8] shadow-xs'
                        : 'bg-[#f8f9fa] dark:bg-[#282828] border-[#dadce0] dark:border-[#3c4043] text-[#5f6368] dark:text-[#9aa0a6] hover:bg-[#e8eaed] dark:hover:bg-[#303134]'
                    }`}
                  >
                    <span className="text-xs font-bold block">Về Nhà</span>
                    <span className="text-[10px] opacity-80">Xem giải chi tiết</span>
                  </button>

                  <button
                    type="button"
                    onClick={() => {
                      setMode('EXAM');
                      setDurationMinutes(50);
                      setShowResult('AFTER_CLOSE');
                      setShowSolution('NEVER');
                    }}
                    className={`p-3 rounded-2xl border text-left transition-all cursor-pointer ${
                      mode === 'EXAM'
                        ? 'bg-[#e8f0fe] dark:bg-[#1e2a38] border-[#1a73e8] dark:border-[#8ab4f8] text-[#1a73e8] dark:text-[#8ab4f8] shadow-xs'
                        : 'bg-[#f8f9fa] dark:bg-[#282828] border-[#dadce0] dark:border-[#3c4043] text-[#5f6368] dark:text-[#9aa0a6] hover:bg-[#e8eaed] dark:hover:bg-[#303134]'
                    }`}
                  >
                    <span className="text-xs font-bold block">Phòng Thi</span>
                    <span className="text-[10px] opacity-80">1 lượt, bảo mật</span>
                  </button>
                </div>

                <div className="grid grid-cols-2 gap-3 text-xs">
                  <div>
                    <label className="block text-[#5f6368] dark:text-[#9aa0a6] mb-1">Thời lượng (phút):</label>
                    <input
                      type="number"
                      value={durationMinutes}
                      onChange={(e) => setDurationMinutes(Number(e.target.value))}
                      className="w-full bg-white dark:bg-[#282828] border border-[#dadce0] dark:border-[#3c4043] rounded-xl px-3 py-2 text-[#202124] dark:text-[#e3e3e3] focus:border-[#1a73e8] dark:focus:border-[#8ab4f8] outline-hidden"
                      min={5}
                      max={300}
                    />
                  </div>

                  <div>
                    <label className="block text-[#5f6368] dark:text-[#9aa0a6] mb-1">Bảng xếp hạng:</label>
                    <button
                      type="button"
                      onClick={() => setEnableLeaderboard(!enableLeaderboard)}
                      className={`w-full py-2 px-3 rounded-xl border font-medium flex items-center justify-center gap-1.5 transition-all cursor-pointer ${
                        enableLeaderboard
                          ? 'bg-[#e6f4ea] dark:bg-[#0f291e] border-[#ceead6] dark:border-[#1d4834] text-[#137333] dark:text-[#5bb98c]'
                          : 'bg-[#f8f9fa] dark:bg-[#282828] border-[#dadce0] dark:border-[#3c4043] text-[#5f6368] dark:text-[#9aa0a6]'
                      }`}
                    >
                      <Trophy className="w-3.5 h-3.5" />
                      {enableLeaderboard ? 'Bật Top & Me' : 'Tắt bảng xếp hạng'}
                    </button>
                  </div>
                </div>

                <details className="rounded-xl border border-[#dadce0] dark:border-[#3c4043] bg-white dark:bg-[#1e1e1e] px-3.5 py-2.5 text-xs">
                  <summary className="cursor-pointer font-medium text-[#202124] dark:text-[#e3e3e3]">Tùy chọn nâng cao: giờ mở/đóng, số lượt, mã vào bài</summary>
                  <div className="mt-3 grid grid-cols-1 sm:grid-cols-2 gap-3">
                    <label className="block text-[#5f6368] dark:text-[#9aa0a6]">Giờ mở (để trống: mở ngay)
                      <input type="datetime-local" value={opensAtLocal} onChange={e => setOpensAtLocal(e.target.value)} className="mt-1 w-full bg-white dark:bg-[#282828] border border-[#dadce0] dark:border-[#3c4043] rounded-xl px-3 py-2 text-[#202124] dark:text-[#e3e3e3]" />
                    </label>
                    <label className="block text-[#5f6368] dark:text-[#9aa0a6]">Giờ đóng (để trống: không hạn)
                      <input type="datetime-local" value={closesAtLocal} onChange={e => setClosesAtLocal(e.target.value)} className="mt-1 w-full bg-white dark:bg-[#282828] border border-[#dadce0] dark:border-[#3c4043] rounded-xl px-3 py-2 text-[#202124] dark:text-[#e3e3e3]" />
                    </label>
                    <label className="block text-[#5f6368] dark:text-[#9aa0a6]">Số lượt làm (1–10)
                      <input type="number" inputMode="numeric" min={1} max={10} placeholder={mode === 'EXAM' ? '1 (phòng thi)' : '3'} value={maxAttemptsText} onChange={e => setMaxAttemptsText(e.target.value)} className="mt-1 w-full bg-white dark:bg-[#282828] border border-[#dadce0] dark:border-[#3c4043] rounded-xl px-3 py-2 text-[#202124] dark:text-[#e3e3e3]" />
                    </label>
                    <label className="block text-[#5f6368] dark:text-[#9aa0a6]">Mã vào bài (4–12 chữ/số, tùy chọn)
                      <input type="text" autoComplete="off" maxLength={12} value={joinCodeText} onChange={e => setJoinCodeText(e.target.value)} className="mt-1 w-full bg-white dark:bg-[#282828] border border-[#dadce0] dark:border-[#3c4043] rounded-xl px-3 py-2 uppercase text-[#202124] dark:text-[#e3e3e3]" />
                    </label>
                  </div>
                  <div className="mt-3 space-y-1.5 text-[#202124] dark:text-[#e3e3e3]">
